function stop(){playing=false;$('play').textContent='Play actuation';}
function setMode(m){stop();mode=m;$('motionControls').hidden=m!=='motion';$('explosionControls').hidden=m!=='explode';for(const x of ['motion','explode']){$(x+'Tab').classList.toggle('active',x===m);$(x+'Tab').setAttribute('aria-selected',x===m)}if(m==='explode'){camera.position.set(250,-300,200);controls.target.set(45,8,20)}controls.update();update()}
$('motionTab').onclick=()=>setMode('motion');$('explodeTab').onclick=()=>setMode('explode');$('play').onclick=()=>{playing=!playing;$('play').textContent=playing?'Pause actuation':'Play actuation';update()};$('travel').oninput=()=>{stop();update()};$('explosion').oninput=update;$('stroke').oninput=()=>{const old=+$('travel').max,f=+$('travel').value/old;$('travel').max=$('stroke').value;$('travel').value=f*+$('stroke').value;update()};for(const id of ['shell','ghost','edges'])$(id).onchange=update;
$('teeth').onclick=()=>{setMode('motion');$('ghost').checked=true;update();camera.position.set(25,5,90);controls.target.set(0,23,17);controls.update()};$('rollers').onclick=()=>{setMode('motion');$('shell').checked=false;update();camera.position.set(100,145,35);controls.target.set(0,40,-15);controls.update()};$('iso').onclick=resetCamera;$('fit').onclick=resetCamera;$('top').onclick=()=>{camera.position.set(0,10,235);controls.target.set(0,10,0);controls.update()};$('reset').onclick=()=>{stop();$('stroke').value=40;$('travel').max=40;$('travel').value=20;$('explosion').value=0;$('shell').checked=true;$('ghost').checked=false;$('edges').checked=false;setMode('motion');resetCamera()};
const roles={rack:'Stiff beveled guide with rounded compliant-tooth reliefs. Four upper rollers act down/inward, two lower rollers support upward.',fixed:'One-piece chassis with integral 5 mm motor mounting land, inclined bearing seats and a braced lower web.',gear:'18-tooth module 2 pinion, oversized 5.30 mm D bore.',set_screw:'M3×4 flat-point screw bears on the D-shaft flat.',shaft:'Reference 5 mm D shaft, rotating with the pinion.',front_axles:'Front M5×16 angled axle; withdraw along its axis before parking clear.',rear_axles:'Rear M5×16 angled axle; removed after the front pair.',upper_rollers:'One of four 45° upper rollers or its inner-race washer.',front_nuts:'Captured front M5 axle nut.',rear_nuts:'Captured rear M5 axle nut.',bottom_axles:'M5×25 lower roller axle.',bottom_nuts:'Lower M5 axle nut; release before withdrawing its bolt.',bottom_rollers:'Lower 625ZZ roller or washer, supporting the flat underside of the rack.',spring_left:'Left four-leaf spring cartridge or its captured mounting nuts. Passive 0.3 mm preload; printable STL is unloaded.',spring_right:'Right four-leaf spring cartridge or its captured mounting nuts. Four leaves constrain axle tilt.',carrier_screws:'Ordinary M3×20 through-bolt retains the spring root; it does not adjust preload.',carrier_nuts:'Captured M3 mounting nut for the spring root.',motor:'NEMA17 reference motor, 42 × 42 × 23 mm.',motor_screws:'M3×12 countersunk motor screw.'};
