try{const r=await fetch('./assets/assembly.json?v=10');if(!r.ok)throw new Error('CAD mesh unavailable');data=await r.json();document.querySelector('.stages').innerHTML=data.stages.map(t=>'<li>'+t.label+'</li>').join('');for(const p of data.parts){const geometry=new THREE.BufferGeometry();geometry.setAttribute('position',new THREE.Float32BufferAttribute(p.vertices.flat(),3));geometry.setIndex(p.triangles.flat());geometry.computeVertexNormals();const mat=new THREE.MeshStandardMaterial({color:p.color,roughness:p.group==='motor'?.58:.4,metalness:p.name.includes('625ZZ')?.78:.16});const mesh=new THREE.Mesh(geometry,mat);mesh.userData=p;mesh.add(new THREE.LineSegments(new THREE.EdgesGeometry(geometry,30),new THREE.LineBasicMaterial({color:0x17232c,transparent:true,opacity:.5})));if(p.spinAxis){for(const sign of [-1,1]){const c=new THREE.Vector3(...p.spinCenter).addScaledVector(new THREE.Vector3(...p.spinAxis),sign*2.51);const g=new THREE.BufferGeometry().setFromPoints([c.clone().add(new THREE.Vector3(4.8,0,0)),c.clone().add(new THREE.Vector3(7.8,0,0))]);mesh.add(new THREE.Line(g,new THREE.LineBasicMaterial({color:0x273b46})));}}if(p.flex_side!==undefined){mesh.userData.springOriginal=geometry.attributes.position.array.slice();mesh.userData.springEdgeOriginal=mesh.children[0].geometry.attributes.position.array.slice();}scene.add(mesh);objects.push(mesh)}$('loading').hidden=true;update();window.FLEX17={data,scene,objects,update,displacement,orientation,lowerLift,springWeight,get mode(){return mode}};}catch(e){$('loading').textContent='The model could not load. Reload the page or download the STEP assembly.';console.error(e)}
try{const report=await(await fetch('./downloads/validation.json?v=10')).json(),n=report.explosion_failures.length+report.motion_failures.length;$('checkTitle').textContent=n?'Geometry issues to review':'No unintended intersections sampled';$('checkSummary').textContent=report.output_pad_update?`The added pad volume has at least ${report.output_pad_update.minimum_continuous_x_gap_mm.toFixed(1)} mm X clearance throughout travel and explosion. Unchanged geometry retains the prior ${report.explosion_samples} explosion and ${report.motion_samples} travel checks. The pad face sits directly on the print plane.`:`${report.explosion_samples} explosion positions and ${report.motion_samples} travel positions checked with OpenCascade solid intersections. ${n} unexpected intersections found. ${report.minimum_rack_frame_gap_mm!==undefined?'Minimum printed-frame gap: '+(report.minimum_rack_frame_gap_is_lower_bound?'≥':'')+report.minimum_rack_frame_gap_mm.toFixed(2)+' mm at tested travel positions. ':''}See exclusions and limits in the report.`}catch(e){$('checkSummary').textContent='The validation report could not be loaded. Download it for the full results.'}
